import {renderTimelineEventBody} from '../../shared/timeline-presentation.js';
import {projectArtistPublic,publicGroupNavigation} from '../../shared/public-projection.js';
import {artist} from './data.js';
export {artist};
import {reconciliationView} from './reconciled-view.js';
import {relationView,publicTimeline} from '../../release-navigation.mjs';
export function render(context){return renderArtist(artist,context);}
/** Research-led visual candidate; full-model/projection equivalence remains executable. */
export function renderArtist(source,{route,helpers:baseHelpers}) {
 const artist=projectArtistPublic(source);
 const pageMediaContext=route.page==='home'?'feature':route.page==='work'?'detail':'card';
 const videoSources=new Set(artist.works.filter(work=>['mv','stage'].includes(work.type)&&work.image).map(work=>typeof work.image==='string'?work.image:work.image.src??work.image.path??work.image.url));
 const h={...baseHelpers,image(asset,alt,options={}){
  const source=typeof asset==='string'?asset:asset?.src??asset?.path??asset?.url;
  return baseHelpers.image(asset,alt,{context:pageMediaContext,...options,...(videoSources.has(source)?{mediaRole:'video-preview',fit:'contain'}:{})});
 }};
 const e=h.escape,k=h.entityKey,go=(p,key=null,q=route.query)=>h.href(artist.slug,p,key,q);
 const view=reconciliationView(artist,h,'wk'),relations=relationView(artist,h,route,'wk');
 const clearFilters=()=>{const q=new URLSearchParams(route.query);q.delete('q');q.delete('type');return go('works',null,q);};
 const historical=m=>m.id==='recvxyICzHOhfP';
 const portraitNote=m=>historical(m)?'2021 · OSEN 历史媒体照':'官方历史资料照 · 拍摄日期未注明';
 const image=m=>m.image?h.image(m.image,m.nameZh+' '+m.name+' · '+portraitNote(m),{fit:'contain',position:'50% 50%'}):`<p class="wk-nameplate">${e(m.nameZh)} · 照片暂缺</p>`;
 const person=m=>`<div class="wk-person-tile" data-media-tile><a class="wk-person ${historical(m)?'wk-person-history':''}" data-portrait-member="${e(m.id)}" href="${go('member',k(m))}"><div class="wk-portrait-image">${image(m)}</div><div class="wk-person-copy"><h3>${e(m.nameZh)}</h3><p class="wk-roman">${e(m.name)}</p><small>${e(portraitNote(m))}</small>${m.historical?'<span class="wk-roster-status">历史成员</span>':''}</div></a></div>`;
 const roster=rows=>{const main=rows.filter(m=>!historical(m)),history=rows.filter(historical);return `<div class="wk-roster-layout"><div class="wk-roster-current">${main.map(person).join('')}</div>${history.length?`<aside class="wk-roster-history"><p class="wk-kicker">历史成员资料</p>${history.map(person).join('')}</aside>`:''}</div>`;};
 const labels={release:'发行',mv:'MV',stage:'舞台'};
 const missing=w=>w.type==='release'?'发行封面暂缺':w.type==='mv'?'MV 预览暂缺':'舞台预览暂缺';
 const record=w=>`<div class="wk-record-tile" data-media-tile><a class="wk-record" data-work-card="${e(k(w))}" data-media-kind="${e(w.type)}" data-has-image="${Boolean(w.image)}" href="${go('work',k(w))}">${w.image?`<div class="wk-sleeve">${h.image(w.image,w.title+' '+({release:'发行封面',mv:'MV预览',stage:'舞台预览'})[w.type],{fit:'contain'})}</div>`:`<div class="wk-missing-inline"><span>${e(missing(w))}</span></div>`}<div class="wk-record-copy"><span class="wk-kicker">${e(labels[w.type])}</span><h3>${e(w.title)}</h3>${w.version?`<p class="wk-record-version">${e(w.version)}</p>`:''}${w.date?`<time datetime="${e(w.date)}">${e(h.dateLabel(w.date,w.precision))}</time>`:''}</div></a></div>`;
 const heading=(text,sub='',chapter='')=>`<div class="wk-heading">${chapter?`<span class="wk-chapter" aria-hidden="true">${e(chapter)}</span>`:''}<div><h1>${e(text)}</h1>${sub?`<p>${e(sub)}</p>`:''}</div></div>`;
 const chapter=(number,title,link,label)=>`<div class="wk-section-label"><div><span class="wk-chapter" aria-hidden="true">${number}</span><h2>${title}</h2></div>${link?`<a href="${link}">${label} <span aria-hidden="true">↗</span></a>`:''}</div>`;
 const catalogNav=()=>`<nav class="wk-catalog-tabs" aria-label="作品分区">${[['release','发行'],['mv','MV'],['stage','舞台']].map(([type,label])=>`<a href="${go('works',null,{type})}"><strong>${label}</strong><span>${artist.works.filter(w=>w.type===type).length}</span></a>`).join('')}</nav>`;
 const nav=`<header class="wk-header"><a class="wk-wordmark" href="${go('home')}">Weeekly<span class="wk-wordmark-dot" aria-hidden="true"></span></a><nav aria-label="团体导航">${[['home','首页'],['members','成员'],['works','作品'],['timeline','时间轴']].map(([p,n])=>`<a href="${go(p)}" ${(route.page==='member'?'members':route.page==='work'?'works':route.page)===p?'aria-current="page"':''}>${n}</a>`).join('')}</nav></header>`;
 let body='';
 if(route.page==='home')body=`<section class="wk-opening"><div class="wk-opening-type"><p class="wk-kicker">WEEEKLY · 人物与音乐</p><h1>Weeekly</h1><p class="wk-opening-index" data-public-group-navigation="weeekly">${e(publicGroupNavigation('weeekly'))}</p><p class="wk-opening-history">成员资料按各自时期列示。</p><a class="wk-text-link" href="${go('works')}">进入作品目录 <span aria-hidden="true">↗</span></a></div><figure class="wk-opening-photo">${h.image(artist.hero,'Weeekly 官方历史团体资料照 · 拍摄日期未注明',{loading:'eager',fit:'contain',caption:true})}</figure></section><section class="wk-people-spread">${chapter('01','成员与时期',go('members'),'成员目录')}${roster(artist.members)}</section><section class="wk-music-spread">${chapter('02','唱片与影像',go('works'),'完整目录')}${catalogNav()}<div class="wk-release-shelf">${artist.works.filter(w=>w.type==='release').slice(0,4).map(record).join('')}</div></section><section class="wk-endnote"><div><span class="wk-chapter" aria-hidden="true">03</span><h2>沿时间阅读</h2><p>发行与重要事项，按日期从最早开始。</p></div><a class="wk-text-link" href="${go('timeline')}">进入时间轴 <span aria-hidden="true">↗</span></a></section>`;
 else if(route.page==='members'){
  const query=(route.query.get('q')||'').normalize('NFKC').toLowerCase(),rows=artist.members.filter(m=>[m.name,m.nameZh].some(v=>v.normalize('NFKC').toLowerCase().includes(query)));
  body=heading('成员目录','原公开阵容与历史成员，按各自资料时期阅读。','01')+`<form class="wk-search wk-member-search" data-member-search><label>搜索成员<input name="q" type="search" value="${e(route.query.get('q')||'')}" placeholder="中文名或原文名"></label><button>查找</button></form><div class="wk-member-directory">${roster(rows)}</div>${!rows.length?`<div class="wk-empty"><p>没有找到匹配的成员。</p><a href="${go('members',null,{})}">清除筛选</a></div>`:''}`;
 }else if(route.page==='member'){
  const m=artist.members.find(x=>k(x)===route.key);
  body=m?`<a class="wk-back" href="${go('members')}">← 返回成员目录</a><article class="wk-person-spread" data-member-id="${e(m.id)}"><figure class="wk-person-image" data-portrait-proportion="${historical(m)?'original-vertical':'original-square'}">${image(m)}<figcaption>${e(portraitNote(m))}</figcaption></figure><div class="wk-person-text"><p class="wk-kicker">人物页 <span aria-hidden="true">/</span> ${e(m.name)}</p>${heading(m.nameZh)}<p class="wk-person-period">${m.historical?'历史成员':'原公开阵容；后续团体活动未确认。'}</p><p class="wk-profile">${e(view.profile(m))}</p>${view.career(m)}${view.sources(m.sources)}${relations.member(m)}<a class="wk-text-link" href="${go('works')}">团体作品目录 <span aria-hidden="true">↗</span></a></div></article>`:heading('没有找到这位成员')+`<a href="${go('members')}">返回成员目录</a>`;
 }else if(route.page==='works'){
  const q=route.query.get('q')||'',type=route.query.get('type')||'all',list=h.filterWorks(artist.works,{query:q,type});
  body=heading('作品目录','正式发行、MV 与舞台分别列示，保留语种及视频版本。','02')+catalogNav()+`<form class="wk-search" data-work-search><label>搜索作品<input name="q" value="${e(q)}" placeholder="输入作品名"></label><label>作品类型<select name="type">${[['all','全部'],['release','发行'],['mv','MV'],['stage','舞台']].map(([v,n])=>`<option value="${v}" ${v===type?'selected':''}>${n}</option>`).join('')}</select></label><button>查找</button></form><p class="wk-result" aria-live="polite">${list.length} 件作品</p><div class="wk-library">${list.map(record).join('')}</div>${!list.length?`<div class="wk-empty"><h2>没有找到匹配的作品。</h2><p>可以换一个名称，或清除当前筛选。</p><a href="${clearFilters()}">清除筛选</a></div>`:''}`;
 }else if(route.page==='work'){
  const w=artist.works.find(x=>k(x)===route.key);
  body=w?`<a class="wk-back" href="${go('works')}">← 返回作品目录</a><article class="wk-work-spread" data-work-key="${e(k(w))}" data-with-media="${Boolean(w.image)}"><div class="wk-detail-sleeve" data-review-media-column>${w.image?h.image(w.image,w.title+' '+({release:'正式发行封面',mv:'MV预览',stage:'舞台预览'})[w.type],{fit:'contain',caption:true}):`<p class="wk-video-label">${e(missing(w))}</p>`}</div><div class="wk-work-copy" data-review-facts-column><p class="wk-kicker">${e(labels[w.type])}</p>${heading(w.title)}${w.version?`<p class="wk-version-tag">${e(w.version)}</p>`:''}<dl class="wk-work-facts">${w.date?`<div><dt>${e(w.dateKind==='music_release'?'音乐发行日期':'日期')}</dt><dd><time datetime="${e(w.date)}">${e(h.dateLabel(w.date,w.precision))}</time></dd></div>${w.dateKind?`<div><dt>日期口径</dt><dd>${e(w.dateKind==='music_release'?'音乐发行日期':w.dateKind)}</dd></div>`:''}`:''}</dl>${h.sources(w.sources)}${relations.detail(w)}${w.videoId?`<a class="wk-text-link" href="${e(h.videoHref(w.videoId))}" target="_blank" rel="noopener">前往官方视频 <span aria-hidden="true">↗</span></a>`:''}</div></article>`:heading('没有找到这件作品')+`<a href="${go('works')}">返回作品目录</a>`;
 }else if(route.page==='timeline'){
  body=heading('时间轴','发行与重要事项，按日期从最早开始。','03')+`<ol class="wk-timeline" data-timeline>${publicTimeline(artist).map(v=>`<li data-event-id="${e(v.id)}" tabindex="-1"><div class="wk-event-date">${v.mainDate?`<time datetime="${e(v.mainDate)}">${e(h.dateLabel(v.mainDate,v.precision))}</time>${v.mainLabel?`<small class="timeline-main-kind">${e(v.mainLabel)}</small>`:''}`:'<span>历史事项</span>'}</div><div class="wk-event-content">${renderTimelineEventBody(v,h,{summaryClass:'wk-event-summary',datesClass:'wk-event-dates',sourcesClass:'wk-sources'})}${relations.event(v)}</div></li>`).join('')}</ol>`;
 }
 return`${nav}<main class="wk-main">${body}</main><footer class="wk-footer"><a class="wk-wordmark" href="${go('home')}">Weeekly</a><p>人物 · 唱片 · 影像</p><a href="${go('home')}">回到首页 ↑</a></footer>`;
}
export function afterRender({root,route,helpers:h}){
 const f=root.querySelector('[data-work-search],[data-member-search]');if(!f)return;
 const cb=event=>{event.preventDefault();const d=new FormData(f),q=new URLSearchParams(route.query);for(const [name,value]of d)q.set(name,String(value));h.navigate(h.href(artist.slug,route.page==='members'?'members':'works',null,q));};
 f.addEventListener('submit',cb);return()=>f.removeEventListener('submit',cb);
}

// Presentation adapters only. Reconciled source fields and review decisions remain unchanged.
export function reconciliationView(artist,h,prefix){
 const e=h.escape;
 const heldURLs=new Set(artist.heldSourceUrls||[]);
 const stamp=d=>d?.value?h.dateLabel(d.value,d.precision):'';
 const sources=(rows=[],label='资料来源')=>{
  const list=rows.map(s=>typeof s==='string'?{url:s,title:'来源'}:s).filter(s=>/^https?:\/\//i.test(s?.url||'')&&!heldURLs.has(s.url));
  return list.length?`<details class="${prefix}-source-notes"><summary>${e(label)}</summary><ul>${list.map(s=>`<li><a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e((s.title||s.label||'来源').replace(/^资料说明[：:]\s*/,''))}</a>${s.publisher?`<span>${e(s.publisher)}</span>`:''}${stamp(s.sourcePublishedAt)?`<p>原刊发布：<time datetime="${e(s.sourcePublishedAt.value)}">${e(stamp(s.sourcePublishedAt))}</time></p>`:''}</li>`).join('')}</ul></details>`:'';
 };
 const dateRow=(label,value,precision)=>value&&h.dateLabel(value,precision)?`<div><dt>${e(label)}</dt><dd><time datetime="${e(value)}">${e(h.dateLabel(value,precision))}</time></dd></div>`:'';
 const profile=m=>{
  return m.displayProfile??m.profile??'';
 };
 const career=m=>{
  const periods=m.careerPeriods||[],rows=m.careerSources||[];
  return `<section class="${prefix}-career"><h2>成员资料与经历</h2>${m.role?`<p>${e(m.role)}</p>`:''}<p>${m.historical?'历史成员':'原公开阵容中的成员；不据此认定当前团体活动'}</p>${periods.map(p=>{
   const ps=rows.filter(s=>(p.sourceIds||[]).includes(s.sourceId||s.id));
   return `<article data-period-id="${e(p.periodId)}"><h3>${e(p.displayName||artist.name)}</h3><p>${p.relationType==='roster_listing'?'官方资料列示':'团体参与经历'}</p><dl>${dateRow(p.startDateBasis==='public_debut'?'团体公开出道':'资料记述起点',p.startDate,p.startPrecision)}${dateRow('资料记述结束',p.endDate,p.endPrecision)}${dateRow('相关公告',p.announcedDate?.value,p.announcedDate?.precision)}${dateRow('资料记述生效',p.effectiveDate?.value,p.effectiveDate?.precision)}</dl>${(p.events||[]).map(v=>`<p>${e(v.label||'')}${v.date?` <time datetime="${e(v.date)}">${e(h.dateLabel(v.date,v.precision))}</time>`:''}</p>`).join('')}${sources(ps,'经历来源')}</article>`;
  }).join('')}${sources(m.officialUrl?[{url:m.officialUrl,title:'个人资料原始来源'}]:[],'个人资料来源')}</section>`;
 };
 const event=t=>{
  const raw=t.canonicalEvent||t,states={announced:'公告',planned:'计划',postponed:'延期公告',cancelled:'取消公告'},types={debut:'出道',release:'发行',member_departure:'成员',contract_end:'合约',notice:'平台公告',other:'活动'};
  const main=raw.eventDate||raw.announcementDate;
  const dates=[['事项日期',raw.eventDate],['公告日期',raw.announcementDate],['计划日期',raw.plannedDate],['生效日期',raw.effectiveDate]].filter(([,d])=>stamp(d));
  const summary=(raw.publicSummary??raw.summary??'').replace(/同日专辑与主打合并为一次发行事件。?/g,'');
  const related=(raw.workIds||[]).filter(id=>artist.works.some(w=>w.id===id));
  return {id:raw.id,title:raw.title,summary,state:states[raw.status]||types[raw.eventType]||'事项',mainDate:main?.value||null,precision:main?.precision||null,dates:dates.length?`<dl class="${prefix}-event-dates">${dates.map(([label,d])=>dateRow(label,d.value,d.precision)).join('')}</dl>`:'',related,sources:sources(raw.sources||[],'事件来源')};
 };
 return {profile,career,event,sources};
}

