import participation from './member-video-relations.json' with {type:'json'};
import {entityKey} from './shared/helpers.js';
const tuple=(work)=>({workId:work.id,videoId:work.videoId,videoType:work.videoType,version:work.version,slotType:work.type==='mv'?'MV':work.type==='stage'?'STAGE':null});
/** Public appearance evidence is independent from native/rating association or group membership. */
export function validateParticipation(edge,artist){
 if(!edge||edge.groupId!==artist.id||edge.slug!==artist.slug||edge.relation!=='appears_in_exact_video'||!artist.members.some(m=>m.id===edge.memberId))return false;
 const matches=artist.works.filter(w=>w.id===edge.workId&&['mv','stage'].includes(w.type));if(matches.length!==1)return false;
 const expected=tuple(matches[0]);
 if(!Object.keys(expected).every(key=>Object.hasOwn(edge,key)&&edge[key]===expected[key]))return false;
 return edge.evidence?.identity?.pageUrl?.startsWith('https://')&&edge.evidence?.identity?.literalName&&edge.evidence?.version?.pageUrl?.startsWith('https://')&&edge.evidence?.version?.videoId===edge.videoId&&Array.isArray(edge.sources)&&edge.sources.length>0;
}
export function verifiedParticipations(artist){return participation.filter(edge=>edge.groupId===artist.id&&edge.slug===artist.slug&&validateParticipation(edge,artist));}
export function videosForMember(artist,member){const edges=verifiedParticipations(artist).filter(e=>e.memberId===member.id);return artist.works.filter(w=>edges.some(e=>e.workId===w.id&&e.videoId===w.videoId));}
export function membersForVideo(artist,work){const edges=verifiedParticipations(artist).filter(e=>e.workId===work.id&&e.videoId===work.videoId);return artist.members.filter(m=>edges.some(e=>e.memberId===m.id));}
export function participationView(artist,h,route,prefix){
 const e=h.escape;
 const photoNote=m=>artist.slug==='cherrybullet'?'2019 官方成员资料照':m.id==='recvxyICzHOhfP'?'2021 · OSEN历史媒体照':'官方历史资料照 · 拍摄日期未注明';
 return {
  member(member){const works=videosForMember(artist,member);return `<section class="${prefix}-participation" data-participation-member="${e(member.id)}"><h2>参与影像</h2>${works.length?`<div class="${prefix}-participation-works">${works.map(work=>`<div class="${prefix}-participation-tile" data-media-tile><a data-member-video="${e(work.videoId)}" href="${h.href(artist.slug,'work',entityKey(work),new URLSearchParams())}">${work.image?h.image(work.image,work.title+' · '+(work.type==='mv'?'MV':'舞台'),{context:'card',mediaRole:'video-preview',fit:'contain'}):''}<span>${e(work.title)}</span><small>${e(work.type==='mv'?'MV':'舞台')} · ${e(work.version||'')}</small></a></div>`).join('')}</div>`:'<p>具体影像参与资料待补充。</p>'}</section>`;},
  video(work){if(!['mv','stage'].includes(work.type))return '';const members=membersForVideo(artist,work);return `<section class="${prefix}-participation" data-participation-video="${e(work.videoId)}"><h2>出演成员</h2>${members.length?`<p>${e(work.type==='mv'?'MV':'舞台')} · ${e(work.version||'')}</p><div class="${prefix}-participation-members">${members.map(m=>`<div class="${prefix}-participation-tile" data-media-tile><a data-video-member="${e(m.id)}" href="${h.href(artist.slug,'member',m.id,new URLSearchParams())}">${m.image?h.image(m.image,m.nameZh,{context:'card',fit:'contain'}):''}<span>${e(m.nameZh)}</span><small>${e(m.name)}</small><small>${e(photoNote(m))}</small></a></div>`).join('')}</div>`:'<p>本版本的成员参与资料待补充。</p>'}</section>`;}
 };
}

import {participationView} from './member-video-relations.mjs';
import {entityKey} from './shared/helpers.js';
import {routeHref} from './shared/router.js';
import {projectTimeline} from './shared/timeline-presentation.js';

/** One axis; reuse original platform event keys rather than invent ready events. */
export function publicTimeline(artist){
  const all=[...artist.timeline,...(artist.platformTimeline??[])];
  return projectTimeline(all,event=>event.publicTimelineKind==='platform_release'?{title:event.title,summary:''}:{})
    .map(view=>view.originalEvent.publicTimelineKind==='platform_release'?{...view,mainLabel:'音乐平台发行日期'}:view);
}

const parents=work=>[...new Set([...(work.parentWorkIds??[]),work.parentWorkId].filter(Boolean))];
/** Exact supplied event/work crosswalks only. No normalized-title or date joins. */
export function releaseRelations(artist,work){
  const releases=artist.works.filter(row=>row.type==='release');
  if(work.type==='release'){
    const ids=new Set(work.releaseFacts?.relatedWorkIds??[]);
    return artist.works.filter(row=>row.type==='mv'?ids.has(row.id):row.type==='stage'&&parents(row).some(id=>ids.has(id)));
  }
  const ids=new Set(work.type==='mv'?[work.id]:parents(work));
  return releases.filter(row=>row.releaseFacts?.relatedWorkIds?.some(id=>ids.has(id)));
}
export function releaseForEvent(artist,eventId){return artist.works.find(row=>row.type==='release'&&row.releaseFacts?.eventId===eventId)??null;}

export function relationView(artist,h,route,prefix){
  const participation=participationView(artist,h,route,prefix);
  const e=h.escape,labels={release:'发行',mv:'MV',stage:'舞台'};
  const link=(row,query=new URLSearchParams())=>`<a data-release-relation="${e(entityKey(row))}" href="${h.href(artist.slug,'work',entityKey(row),query)}">${e(row.title)} · ${labels[row.type]}${row.version?' · '+e(row.version):''}</a>`;
  const stamp=(label,value)=>value?.value?`<p>${e(label)}：<time datetime="${e(value.value)}">${e(h.dateLabel(value.value,value.precision))}</time></p>`:'';
  return {
    member:participation.member,
    event(event){
      const release=releaseForEvent(artist,event.id);
      const query=new URLSearchParams(route.query);query.set('event',event.id);
      if(release)return link(release,query);
      return event.related.filter(id=>artist.works.some(row=>entityKey(row)===id)).map(id=>link(artist.works.find(row=>entityKey(row)===id),query)).join('');
    },
    detail(work){
      const related=releaseRelations(artist,work),facts=work.releaseFacts;
      const canonicalDate=facts?.eventDate;
      const date=facts?stamp(facts.kind+'发行',canonicalDate)+stamp('公告',facts.announcementDate):'';
      const sources=facts?.sources?.length?`<details><summary>发行资料来源</summary>${h.sources(facts.sources)}</details>`:'';
      const counterpart=work.type==='release'?'相关影像':'所属发行';
      // Parent links are factual navigation; no candidate/native record substitution.
      return `${participation.video(work)}<section class="${prefix}-related" data-release-relations>${date}${sources}<h2>${counterpart}</h2>${related.length?`<ul>${related.map(row=>`<li>${link(row)}</li>`).join('')}</ul>`:`<p>关联资料待补充。</p>`}${facts?`<a data-release-timeline href="${h.href(artist.slug,'timeline',null,{event:facts.eventId})}">查看发行时间轴 →</a>`:''}</section>`;
    }
  };
}

/** A timeline entry becomes the return context; no global ID/anchor guessing. */
export function timelineOrigin(route,target){
  if(route.page!=='timeline'||target.page!=='work')return null;
  const event=target.query.get('event');
  const query=new URLSearchParams(route.query);if(event)query.set('event',event);
  return routeHref({...route,query});
}

import {resolveMediaPresentation} from './media-policy.js';

const entities = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
export const escape = value => String(value ?? '').replace(/[&<>"']/g, char => entities[char]);
export const entityKey = entity => entity?.id != null && entity.id !== '' ? String(entity.id) : entity?.candidateKey ? String(entity.candidateKey) : null;
export function href(slug, page = 'home', key = null, query = {}) {
  const parts = [slug];
  if (page !== 'home') parts.push(page);
  if (key !== null && key !== undefined) parts.push(String(key));
  const params = query instanceof URLSearchParams ? query : new URLSearchParams(Object.entries(query).filter(([, value]) => value !== null && value !== undefined && value !== ''));
  return `#/${parts.map(encodeURIComponent).join('/')}${params.size ? `?${params}` : ''}`;
}
export function parseDate(value, precision) {
  if (typeof value !== 'string') return null;
  const match = /^(\d{4})(?:-(\d{2})(?:-(\d{2}))?)?$/.exec(value);
  if (!match) return null;
  const [, yearText, monthText, dayText] = match;
